     9→
    10→// Configure HTMX to include CSRF token in all requests
    11→document.addEventListener('DOMContentLoaded', function() {
    12→    // Get CSRF token from cookie
    13→    function getCookie(name) {
    14→        let cookieValue = null;
    15→        if (document.cookie && document.cookie !== '') {
    16→            const cookies = document.cookie.split(';');
    17→            for (let i = 0; i < cookies.length; i++) {
    18→                const cookie = cookies[i].trim();
    19→                if (cookie.substring(0, name.length + 1) === (name + '=')) {
    20→                    cookieValue = decodeURIComponent(cookie.substring(name.length + 1));
    21→                    break;
    22→                }
    23→            }
    24→        }
    25→        return cookieValue;
    26→    }
    27→
    28→    const csrftoken = getCookie('csrftoken');
    29→
    30→    // Add CSRF token to all HTMX requests
    31→    document.body.addEventListener('htmx:configRequest', function(event) {
    32→        event.detail.headers['X-CSRFToken'] = csrftoken;
    33→    });
    34→
    35→    // Handle HTMX errors
    36→    document.body.addEventListener('htmx:responseError', function(event) {
    37→        console.error('HTMX Error:', event.detail);
    38→        // You could show a toast notification here
    39→    });
    40→
    41→    // Add loading class to body during HTMX requests
    42→    document.body.addEventListener('htmx:beforeRequest', function(event) {
    43→        const indicator = event.detail.elt.querySelector('.htmx-indicator');
    44→        if (indicator) {
    45→            indicator.style.display = 'inline-block';
    46→        }
    47→    });
    48→
    49→    document.body.addEventListener('htmx:afterRequest', function(event) {
    50→        const indicator = event.detail.elt.querySelector('.htmx-indicator');
    51→        if (indicator) {
    52→            indicator.style.display = 'none';
    53→        }
    54→    });
    55→
    56→    // Handle HTMX redirect responses (for Django login required)
    57→    document.body.addEventListener('htmx:beforeSwap', function(event) {
    58→        // Check if response is a redirect to login page
    59→        if (event.detail.xhr.status === 403 || event.detail.xhr.status === 401) {
    60→            window.location.href = '/accounts/login/';
    61→        }
    62→    });
    63→});
