    69→// Register Alpine.js global stores when Alpine is ready
    70→document.addEventListener('alpine:init', () => {
    71→    // Toast notification store
    72→    Alpine.store('toasts', {
    73→        items: [],
    74→
    75→        add(message, type = 'info', duration = 5000) {
    76→            const id = Date.now();
    77→            this.items.push({ id, message, type });
    78→
    79→            if (duration > 0) {
    80→                setTimeout(() => this.remove(id), duration);
    81→            }
    82→        },
    83→
    84→        remove(id) {
    85→            this.items = this.items.filter(item => item.id !== id);
    86→        },
    87→
    88→        success(message) {
    89→            this.add(message, 'success');
    90→        },
    91→
    92→        error(message) {
    93→            this.add(message, 'danger');
    94→        },
    95→
    96→        warning(message) {
    97→            this.add(message, 'warning');
    98→        },
    99→
   100→        info(message) {
   101→            this.add(message, 'info');
   102→        }
   103→    });
   104→
   105→    // Sidebar state store
   106→    Alpine.store('sidebar', {
   107→        open: false,
   108→
   109→        toggle() {
   110→            this.open = !this.open;
   111→        },
   112→
   113→        close() {
   114→            this.open = false;
   115→        }
   116→    });
   117→
   118→    // Global modal helper
   119→    Alpine.data('modal', (initialOpen = false) => ({
   120→        open: initialOpen,
   121→
   122→        show() {
   123→            this.open = true;
   124→            document.body.classList.add('modal-open');
   125→        },
   126→
   127→        hide() {
   128→            this.open = false;
   129→            document.body.classList.remove('modal-open');
   130→        },
   131→
   132→        toggle() {
   133→            this.open ? this.hide() : this.show();
   134→        }
   135→    }));
   136→
   137→    // Dropdown helper
   138→    Alpine.data('dropdown', () => ({
   139→        open: false,
   140→
   141→        toggle() {
   142→            this.open = !this.open;
   143→        },
   144→
   145→        close() {
   146→            this.open = false;
   147→        }
   148→    }));
   149→
   150→    // Confirm dialog helper
   151→    Alpine.data('confirmDialog', () => ({
   152→        open: false,
   153→        title: '',
   154→        message: '',
   155→        confirmText: 'Confirmar',
   156→        cancelText: 'Cancelar',
   157→        onConfirm: null,
   158→
   159→        show(options = {}) {
   160→            this.title = options.title || 'Confirmar';
   161→            this.message = options.message || 'Tem certeza?';
   162→            this.confirmText = options.confirmText || 'Confirmar';
   163→            this.cancelText = options.cancelText || 'Cancelar';
   164→            this.onConfirm = options.onConfirm || null;
   165→            this.open = true;
   166→        },
   167→
   168→        confirm() {
   169→            if (typeof this.onConfirm === 'function') {
   170→                this.onConfirm();
   171→            }
   172→            this.open = false;
   173→        },
   174→
   175→        cancel() {
   176→            this.open = false;
   177→        }
   178→    }));
   179→});
