   185→// Format currency (Brazilian Real)
   186→function formatCurrency(value) {
   187→    return new Intl.NumberFormat('pt-BR', {
   188→        style: 'currency',
   189→        currency: 'BRL'
   190→    }).format(value);
   191→}
   192→
   193→// Format date (Brazilian format)
   194→function formatDate(dateString) {
   195→    const date = new Date(dateString);
   196→    return new Intl.DateTimeFormat('pt-BR').format(date);
   197→}
   198→
   199→// Format datetime (Brazilian format)
   200→function formatDateTime(dateString) {
   201→    const date = new Date(dateString);
   202→    return new Intl.DateTimeFormat('pt-BR', {
   203→        dateStyle: 'short',
   204→        timeStyle: 'short'
   205→    }).format(date);
   206→}
