   208→// Debounce function for search inputs
   209→function debounce(func, wait) {
   210→    let timeout;
   211→    return function executedFunction(...args) {
   212→        const later = () => {
   213→            clearTimeout(timeout);
   214→            func(...args);
   215→        };
   216→        clearTimeout(timeout);
   217→        timeout = setTimeout(later, wait);
   218→    };
   219→}
