   225→// Custom HTMX extension for handling Django messages
   226→htmx.defineExtension('django-messages', {
   227→    onEvent: function(name, evt) {
   228→        if (name === 'htmx:afterSwap') {
   229→            // Look for messages in the response
   230→            const messagesContainer = evt.detail.elt.querySelector('[data-messages]');
   231→            if (messagesContainer && window.Alpine) {
   232→                const messages = JSON.parse(messagesContainer.dataset.messages || '[]');
   233→                messages.forEach(msg => {
   234→                    Alpine.store('toasts').add(msg.message, msg.tags);
   235→                });
   236→            }
   237→        }
   238→    }
   239→});
